mapper.select:

WHERE device_id = #{deviceId}
  AND reply = #{reply}
  AND request_id IN

    #{requestId}

ORDER BY time DESC

SELECT count(*)
FROM device_message


        AND time >= #{createTime}

SELECT date_bin(1h, time) AS time, count_if(upstream = 1) AS upstream_count, count_if(upstream = 0) AS downstream_count FROM device_message
AND time >= #{startTime}
AND time <= #{endTime}
GROUP BY date_bin(1h, time)
